$docx = "C:\Users\admin\AppData\Local\Temp\wps-windows-check\20261022T120934Z-f8ed7bd-eval\run-1\convert-pdf-to-docx\supplier.docx"
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead($docx)
foreach ($name in @('word/document.xml','word/styles.xml','word/numbering.xml')) {
  $entry = $zip.Entries | Where-Object { $_.FullName -eq $name }
  if ($entry) {
    $reader = New-Object System.IO.StreamReader($entry.Open())
    $xml = $reader.ReadToEnd(); $reader.Close()
    $numPr = ([regex]::Matches($xml,'<w:numPr>')).Count
    $num = ([regex]::Matches($xml,'<w:num ')).Count
    $tbl = ([regex]::Matches($xml,'<w:tbl>')).Count
    "{0}: numPr={1} w:num={2} tbl={3} bytes={4}" -f $name,$numPr,$num,$tbl,$xml.Length
  } else { "$name : MISSING" }
}
$zip.Dispose()

Add-Type -AssemblyName System.IO.Compression.FileSystem
$z = [IO.Compression.ZipFile]::OpenRead("C:\Users\admin\AppData\Local\Temp\wps-windows-check\20261022T120934Z-f8ed7bd-eval\run-1\convert-markdown-to-docx\guide.docx")
