Add-Type -AssemblyName System.IO.Compression.FileSystem
$p = "C:\Users\admin\AppData\Local\Temp\wps-windows-check\20261022T120934Z-f8ed7bd-eval\run-2\convert-docx-to-pptx\brief.pptx"
$zip = [System.IO.Compression.ZipFile]::OpenRead($p)
$slides = $zip.Entries | Where-Object { $_.FullName -match '^ppt/slides/slide\d+\.xml$' } | Sort-Object { [int]($_.Name -replace '\D','') }
foreach ($s in $slides) {
  $r = New-Object System.IO.StreamReader($s.Open())
  [xml]$xml = $r.ReadToEnd(); $r.Close()
  $texts = $xml.GetElementsByTagName('a:t') | ForEach-Object { $_.InnerText }
  "=== $($s.Name) ==="
  $texts | ForEach-Object { "  [$_]" }
}
$zip.Dispose()
